def answer(L, R):
    """Write a python function to find two distinct numbers such that their lcm lies within the given range.

    Return two distinct numbers in ``[L, R]`` whose lcm is also in
    ``[L, R]``.  ``(L, L + L)`` works whenever ``L + L <= R``, since
    ``lcm(L, L + L) == L + L``.  No such pair can exist when
    ``L + L > R`` (for distinct ``a < b`` in ``[L, R]``, ``lcm(a, b)``
    is either ``b`` only if ``a`` divides ``b``, which would require
    ``b >= a + a >= L + L > R``, or at least ``b + b > R``), so
    ``(-1, -1)`` is returned in that case.
    """
    if L < 1 or R < L + L:
        return (-1, -1)
    return (L, L + L)
